using UnityEngine;
// Live observations only: future crusade/restoration milestones are design proposals, not invented campaign facts.
public static class SiegeCharacterContext
{
    const int OrbanEnough=112;
    public static bool CannonsSatisfied=>DailyLifeEvents.I("iCannons")>=OrbanEnough;
    public static bool NewCannonConversation=>!CourtConversationData.Read(5,"cannontheory")||CannonsSatisfied&&!CourtConversationData.Read(5,"cannonanswer");
    public static string CannonTheory=>"Orban sets down his cup. ‘How many cannons does a city need? Enough for the places you cannot watch, and another for the gun that cracks when you need it.’ You ask whether he has a number in mind. ‘Of course. But if I tell the clerks, they will purchase precisely that many and announce that the siege has been attended to. Let us see what the workshops can do first.’";
    public static string CannonAnswer=>"Orban looks over the inventory twice. ‘One hundred and twelve. Yes. I should be ashamed to call that too few.’\n\nYou ask why one hundred and twelve.\n\n‘My father’s account book had fourteen pages, eight lines to a page. When he filled it he would say we could now afford to fear nothing except the next account book. I believed him until the winter.’ He returns the inventory. ‘Look at the powder stores, Majesty. Guns do not eat round numbers.’";
    public static string Text(int person)
    {
        if(!VariableSingleton.HasSiegeStarted())return person==1?"‘The chain closes a passage; it does not provision a ship. Decide what the fleet must be ready to do when the passage is threatened.’":person==5?"‘The workshops still have time to finish what we order. Powder and men to serve the pieces should be planned beside the guns.’":"‘We are preparing for a siege, not yet enduring one. Every task completed now is one we need not attempt under fire.’";
        int day=VariableSingleton.SiegeDay;
        string phase=day>60?"‘They have held us here longer than many men thought possible. We must plan for the next month without pretending that enduring the last has made us inexhaustible.’":day>30?"‘The first weeks are behind us. Watches, supplies and promises must now be renewed by men who have already paid for them once.’":"‘We are still learning where the pressure will fall. The first reports should correct our preparations, not merely confirm them.’";
        if(person==1||person==101){bool chain=VariableSingleton.GetBoolVariable("bGoldenHornChain");int ships=DailyLifeEvents.I("iShips");return (chain?"‘The chain still bars the harbour entrance. It has not defeated the enemy fleet outside it.’":"‘The chain no longer protects the harbour entrance. Our captains must reckon with that before calling an anchorage safe.’")+"\n\n"+(ships==0?"‘We have no ships ready for service. A naval order will not conjure a crew and a hull.’":NavalState.Uncontested?"‘We outnumber the Ottoman ships now. That gives us choices, not an undertaking from the sea to spare us losses.’":"‘The seas remain contested. A distant raid and the protection of the harbour cannot be promised by the same hulls at once.’");}
        if(person==6||person==103){float wall=VariableSingleton.Instance.EnduringWall.GetHealth();return wall<.5f?"‘The active defensive wall is below half integrity. Inspect it before committing resources to an impressive new project. Old damage does not become less urgent because we have grown used to seeing it.’":"‘The active wall still has more than half its integrity. That is remaining strength, not a certificate that the next bombardment will spare it. Keep watching the approaches as well as the masonry.’";}
        if(person==5)return DailyLifeEvents.I("iAmmunition")<10?"‘We are close to asking metal to do the work of powder. Count the ammunition before ordering another discharge merely to reassure the council.’":DailyLifeEvents.I("iCannons")<10?"‘We still have few guns ready. I would welcome more, provided the powder, positions and men are counted in the same proposal.’":"‘We have added guns. Now we must put them where they can work, keep them supplied and resist the temptation to answer every enemy movement with a discharge.’";
        if(person==7){int religion=DailyLifeEvents.I("iReligion"),aid=DailyLifeEvents.I("iAidState0");return religion==1||religion==2?aid==2?"‘Help from Rome has arrived. We can speak of what it brought instead of arguing over a promise. It has not, by itself, healed the quarrel within the City.’":aid==1?"‘Rome has accepted the appeal, but an expedition under way is not an army at our walls. Do not call a promise a crusade merely because the City needs one.’":"‘You have accepted the Union. That is an obligation; it is not evidence that a relief fleet has sailed. We must distinguish the two when we speak to the people.’":"‘The quarrel over the Union remains with us. Men may oppose my cause and still defend these walls honestly. We should not require the Sultan to teach us that distinction.’";}
        return phase;
    }
}
